// ============================================================
//  Store — общение с локальным сервером. Данные = JSON-файлы в vault.
// ============================================================
function taskWriteAllowed(source, notify = false) {
  if (!State._tasksLoadError) return true;
  clearTimeout(Store._timers.tasks);
  if (notify) {
    const now = Date.now();
    if (now - (State._tasksWriteBlockedNoticeAt || 0) > 2000) {
      State._tasksWriteBlockedNoticeAt = now;
      toast(t('Изменения квестов заблокированы до восстановления данных'));
    }
  }
  console.error(`${source} blocked`, 'tasks', State._tasksLoadError);
  return false;
}
function validateSettingsPayload(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  if (value.skills !== undefined && !Array.isArray(value.skills)) return false;
  for (const key of ['xp', 'gold', 'curve', 'focus']) {
    if (value[key] !== undefined && (!value[key] || typeof value[key] !== 'object' || Array.isArray(value[key]))) return false;
  }
  return true;
}
function settingsWriteAllowed(source, notify = false) {
  if (!State._settingsLoadError) return true;
  clearTimeout(Store._timers.settings);
  if (notify) {
    const now = Date.now();
    if (now - (State._settingsWriteBlockedNoticeAt || 0) > 2000) {
      State._settingsWriteBlockedNoticeAt = now;
      toast(t('Изменения настроек заблокированы до восстановления данных'));
    }
  }
  console.error(`${source} blocked`, 'settings', State._settingsLoadError);
  return false;
}
const Store = {
  _timers: {},
  async load(name, fallback) {
    try {
      const r = await fetch(`/api/data/${name}`);
      if (r.status === 401) { handleAccountSessionExpired(); throw new Error('session expired'); }
      if (r.status === 404) return structuredClone(fallback);
      if (!r.ok) throw new Error('load ' + r.status);
      const v = await r.json();
      // Защита от краша рендера: null/undefined или несовпадение типа с дефолтом → дефолт.
      // Без неё поле, сохранённое как null (или массив вместо объекта), даёт Object.entries(null)/null.filter →
      // падал весь раздел (Календарь/Статистика у Виолы). Тип сверяем с fallback.
      if (v == null) return structuredClone(fallback);
      if (Array.isArray(fallback) && !Array.isArray(v)) return structuredClone(fallback);
      if (fallback && typeof fallback === 'object' && !Array.isArray(fallback) && (typeof v !== 'object' || Array.isArray(v))) return structuredClone(fallback);
      return v;
    } catch (e) {
      console.error('load', name, e);
      return structuredClone(fallback);
    }
  },
  // Для экранов, где молчаливая подмена повреждённых данных дефолтом опасна.
  // Возвращает причину отдельно: вызывающий может показать recovery UI и НЕ
  // сохранить fallback поверх исходного файла до явного решения человека.
  async loadChecked(name, fallback, validate) {
    try {
      const r = await fetch(`/api/data/${name}`);
      if (r.status === 401) { handleAccountSessionExpired(); return { value: structuredClone(fallback), error: 'session' }; }
      if (r.status === 404) return { value: structuredClone(fallback), error: '' };
      if (!r.ok) throw new Error('load ' + r.status);
      const value = await r.json();
      if (value == null || (validate && !validate(value))) throw new Error('invalid data');
      return { value, error: '' };
    } catch (error) {
      console.error('loadChecked', name, error);
      const invalid = error && (error.message === 'invalid data' || error.name === 'SyntaxError');
      return { value: structuredClone(fallback), error: invalid ? 'invalid' : 'load' };
    }
  },
  save(name, obj) {
    if (name === 'tasks' && !taskWriteAllowed('save', true)) return false;
    if (name === 'settings' && !settingsWriteAllowed('save', true)) return false;
    clearTimeout(this._timers[name]);
    this._timers[name] = setTimeout(() => this._put(name, obj), 250);
    return true;
  },
  // Сохранить НЕМЕДЛЕННО и дождаться. Нужно там, где сразу после записи идёт чтение с сервера:
  // save() дебаунсится на 250 мс, а initApp() читает мгновенно — и получает ещё не сохранённое.
  // Именно так онбординг терял выбранные сферы и подставлял вместо них дефолтные.
  async saveNow(name, obj) {
    if (name === 'tasks' && !taskWriteAllowed('saveNow', true)) return false;
    if (name === 'settings' && !settingsWriteAllowed('saveNow', true)) return false;
    clearTimeout(this._timers[name]);
    return this._put(name, obj);
  },
  async _put(name, obj) {
    // Последний рубеж: прямые Store._put('tasks', ...) тоже не могут
    // перезаписать повреждённый/недоступный файл fallback-массивом.
    if (name === 'tasks' && !taskWriteAllowed('_put', true)) return false;
    if (name === 'settings' && !settingsWriteAllowed('_put', true)) return false;
    try {
      const r = await fetch(`/api/data/${name}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(obj),
      });
      if (r.status === 401) { handleAccountSessionExpired(); return false; }
      if (!r.ok) throw new Error('save ' + r.status);
      return true;
    } catch (e) { console.error('save', name, e); toast('⚠️ Не удалось сохранить'); return false; }
  },
};

