// Ищем по имени; если сфера кастомная — падаем на архетип (те же корни, что у питомцев)
function sphereGuide(name) {
  const n = String(name || '').trim();
  if (SPHERE_GUIDE[n]) return SPHERE_GUIDE[n];
  const hit = Object.keys(SPHERE_GUIDE).find((k) => k.toLowerCase() === n.toLowerCase());
  return hit ? SPHERE_GUIDE[hit] : null;
}

