let _calendarDialogScrollLock = null;
function lockCalendarDialogScroll() {
  document.documentElement.classList.add('calendar-task-open');
  if (_calendarDialogScrollLock || !document.body) return;
  const body = document.body;
  _calendarDialogScrollLock = {
    x: window.scrollX, y: window.scrollY,
    position: body.style.position, top: body.style.top, left: body.style.left,
    right: body.style.right, width: body.style.width, overflow: body.style.overflow,
  };
  body.style.position = 'fixed';
  body.style.top = `-${_calendarDialogScrollLock.y}px`;
  body.style.left = `-${_calendarDialogScrollLock.x}px`;
  body.style.right = '0';
  body.style.width = '100%';
  body.style.overflow = 'hidden';
}
function unlockCalendarDialogScroll() {
  if (document.querySelector('#cal-task-modal, #desire-pop, #cal-sub-ov')) return;
  document.documentElement.classList.remove('calendar-task-open');
  const lock = _calendarDialogScrollLock;
  _calendarDialogScrollLock = null;
  if (!lock || !document.body) return;
  const body = document.body;
  body.style.position = lock.position;
  body.style.top = lock.top;
  body.style.left = lock.left;
  body.style.right = lock.right;
  body.style.width = lock.width;
  body.style.overflow = lock.overflow;
  window.scrollTo(lock.x, lock.y);
}
function closeDesirePicker({ restoreFocus = true } = {}) {
  const overlay = document.getElementById('desire-pop');
  if (!overlay) return false;
  const target = restoreFocus && overlay._returnFocus && overlay._returnFocus.isConnected ? overlay._returnFocus : null;
  if (overlay._desireApp) overlay._desireApp.inert = !!overlay._desireAppWasInert;
  document.documentElement.classList.remove('desire-picker-open');
  overlay.remove();
  unlockCalendarDialogScroll();
  if (target) requestAnimationFrame(() => focusPathChoiceTarget(target));
  return true;
}
function handleDesirePickerKeydown(event) {
  const overlay = document.getElementById('desire-pop');
  if (!overlay || !overlay.contains(event.target)) return false;
  if (event.key === 'Escape') {
    event.preventDefault(); event.stopPropagation(); closeDesirePicker(); return true;
  }
  if (event.key !== 'Tab') return false;
  const focusable = pathChoiceFocusable(overlay);
  if (!focusable.length) {
    event.preventDefault(); focusPathChoiceTarget(document.getElementById('desire-title')); return true;
  }
  const index = focusable.indexOf(document.activeElement);
  if (index < 0 || (!event.shiftKey && index === focusable.length - 1) || (event.shiftKey && index === 0)) {
    event.preventDefault(); focusPathChoiceTarget(event.shiftKey ? focusable[focusable.length - 1] : focusable[0]);
  }
  return true;
}
// Поп-ап выбора желания при завершении сложного квеста. Значения forced/neutral/hyped
// и их награды остаются прежними; этот слой отвечает только за честный, доступный выбор.
function openDesirePicker(taskId, returnFocus = document.activeElement) {
  const existing = document.getElementById('desire-pop');
  if (existing) {
    requestAnimationFrame(() => focusPathChoiceTarget(document.getElementById('desire-title')));
    return existing;
  }
  const task = questById(taskId); if (!task) return null;
  const overlay = document.createElement('div');
  overlay.id = 'desire-pop';
  overlay.className = 'modal-overlay cal-task-overlay desire-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-labelledby', 'desire-title');
  overlay.setAttribute('aria-describedby', 'desire-task-summary desire-science');
  overlay.setAttribute('lang', lang());
  overlay._returnFocus = returnFocus && typeof returnFocus.focus === 'function' ? returnFocus : null;
  overlay._completionFocus = taskCompletionFocusPlan(task.id, returnFocus);
  overlay.innerHTML = `<div class="desire-box">
    <button type="button" class="modal-x" data-action="desire-cancel" aria-label="${esc(t('Закрыть'))}">✕</button>
    <h3 id="desire-title" tabindex="-1">${esc(t('Насколько ты хотел это сделать?'))}</h3>
    <p class="muted" id="desire-task-summary"><span aria-hidden="true">🔥</span> <span data-noi18n>«${esc(task.title)}»</span> — ${esc(t('Это сложный квест. Честный ответ влияет на XP и твою энергию.'))}</p>
    <div class="desire-btns">
      <button type="button" class="desire-opt forced" data-action="desire-pick" data-id="${task.id}" data-desire="forced"><span class="d-emoji" aria-hidden="true">😮‍💨</span><b>${esc(t('Через силу'))}</b><small>+${Math.round(GRIT_BONUS * 100)}% XP · ${esc(t('расход энергии ×1,5'))}</small></button>
      <button type="button" class="desire-opt neutral" data-action="desire-pick" data-id="${task.id}" data-desire="neutral"><span class="d-emoji" aria-hidden="true">🙂</span><b>${esc(t('Нормально'))}</b><small>${esc(t('обычные XP и энергия'))}</small></button>
      <button type="button" class="desire-opt hyped" data-action="desire-pick" data-id="${task.id}" data-desire="hyped"><span class="d-emoji" aria-hidden="true">⚔️</span><b>${esc(t('В кураже!'))}</b><small>🔥 ${esc(t('Хайп · расход энергии ниже'))}</small></button>
    </div>
    <p class="desire-sci muted" id="desire-science">${esc(t('Воля против сопротивления истощает сильнее (ego depletion), поток — меньше (flow). Поэтому здоровая середина устойчивее, чем вечный форсаж.'))}</p>
  </div>`;
  const appRoot = document.getElementById('app');
  overlay._desireApp = appRoot;
  overlay._desireAppWasInert = !!(appRoot && appRoot.inert);
  if (appRoot) appRoot.inert = true;
  lockCalendarDialogScroll();
  document.documentElement.classList.add('desire-picker-open');
  overlay.addEventListener('keydown', handleDesirePickerKeydown);
  overlay.addEventListener('click', (event) => { if (event.target === overlay) closeDesirePicker(); });
  document.body.appendChild(overlay);
  requestAnimationFrame(() => focusPathChoiceTarget(document.getElementById('desire-title')));
  return overlay;
}
// Поп-ап выбора нескольких категорий для квеста (иллюстрация = работа + творчество)
function openCategoryPicker(taskId) {
  if (document.getElementById('cat-pop')) return;
  const t = questById(taskId); if (!t) return;   // ⚠️ `t` здесь — задача, глобальная t() затенена → переводим через t18()
  const ids = taskSkills(t), lids = taskLayers(t);
  const opt = (s, depth) => {
    const checked = ids.includes(s.id);
    const isLayer = lids.includes(s.id);
    // Три состояния сферы: не участвует · фон · основная. Раньше их было два, и «участвует»
    // означало делёж опыта — поэтому отметить правду («мяч это и тело, и отдых») было
    // невыгодно. Теперь фон добавляет сверху, и честность больше ничего не стоит.
    return `<label class="cat-opt ${depth ? 'is-sub' : ''}" style="padding-left:${10 + depth * 18}px">
      <input type="checkbox" data-action="toggle-cat" data-id="${t.id}" data-skill="${s.id}" ${checked ? 'checked' : ''}/>
      <span class="t-cat" style="--c:${esc(s.color)}">${depth ? '↳ ' : ''}${esc(s.name)}</span>
      <button type="button" class="cat-role${isLayer ? ' is-layer' : (checked ? ' is-main' : '')}" data-action="toggle-layer" data-id="${t.id}" data-skill="${s.id}">${isLayer ? t18('фон') : (checked ? t18('основная') : '+ ' + t18('фон'))}</button>
    </label>`;
  };
  // Полная иерархия любой глубины (Учёба › Школа › Математика) — фидбек #19
  let list = '';
  const walk = (parentId, depth) => { if (depth > 6) return; for (const s of State.settings.skills.filter((x) => (x.parentId || null) === parentId)) { list += opt(s, depth); walk(s.id, depth + 1); } };
  walk(null, 0);
  const ov = document.createElement('div'); ov.id = 'cat-pop'; ov.className = 'modal-overlay';
  ov.innerHTML = `<div class="desire-box"><button class="modal-x" data-action="close-cats">✕</button>
    <h3>${t18('Сферы квеста')}</h3>
    <p class="muted">«${esc(t.title)}» · ${t18('основная получает опыт и время. Фон — сферы, которые дело задевает попутно: они держат форму и дают немного опыта сверху, не отнимая у основной.')}</p>
    <div class="cat-list">${list}</div>
    <div class="settings-actions" style="margin-top:14px"><button class="btn" data-action="close-cats">${t18('Готово')}</button></div></div>`;
  document.body.appendChild(ov);
}

function itemXp(it) {
  const xp = State.settings.xp, mult = xp.difficulty[it.difficulty] ?? 1;
  const base = (Number(it.estimateMin) || 0) * xp.perMinute * mult + xp.completionBonus;
  const gb = gearBonus(it.skillId), gearMul = (1 + gb.xpPct / 100) * (it.difficulty === 'hard' ? (1 + gb.hardXpPct / 100) : 1); // гир бустит XP (реликвия — по сфере)
  return Math.max(1, Math.round(base * (1 + skillPerkBonus(it.skillId) / 100) * (1 + lootBoostPct() / 100) * (1 + hypePct() / 100) * gearMul));
}
function itemGold(it) {
  const g = State.settings.gold || DEFAULT_SETTINGS.gold, mult = State.settings.xp.difficulty[it.difficulty] ?? 1;
  const base = Math.round((Number(it.estimateMin) || 0) * g.perMinute * mult) + g.completionBonus;
  return Math.max(1, Math.round(base * (1 + (gearBonus().goldPct + (skillPerks(it.skillId).goldPct || 0)) / 100))); // амулет + перк древа бустят золото
}

// ---- Единый поток событий (квесты + привычки + цели) ----
// Категории квеста: массив id сфер. Back-compat: старые задачи с одним skillId.
function taskSkills(t) { return (t.skillIds && t.skillIds.length) ? t.skillIds : (t.skillId ? [t.skillId] : []); }
// ══ СЛОИ у обычного дела (этап 2 LIFE-CAPTURE-PLAN.md) ═════════════════════════════════
// Проблема, которую это чинит: мульти-сфера выше ДЕЛИТ опыт (`shareInt`) — отметив «мяч =
// Тело + Отдых», человек получал по половине в каждую. То есть честность наказывалась, и
// приходилось мучительно выбирать ОДНУ сферу («мяч — это отдых или развитие тела?»). Это и
// был «налог на классификацию» из разбора.
// Слой — другая сущность: основная сфера получает СВОЁ полностью, фоновая — бонус СВЕРХУ.
// Никто ничего не теряет, поэтому отмечать правду становится выгодно.
// Фон намеренно слабее: держит Форму (главное) + небольшой XP. Если бы фон догонял основную,
// «был в среде» стало бы выгоднее «занимался целенаправленно» — и мотивация к осознанной
// практике сломалась бы. Время (`min`) фон не даёт вовсе — иначе вернулись бы «>24 ч в сутки».
const LAYER_SHARE = 0.2;   // доля XP основного дела, которую получает каждый фоновый слой
const LAYER_MAX = 3;       // больше трёх фонов — это уже не дело, а эпизод
function taskLayers(t) {
  const prim = taskSkills(t);
  return (t.layers || []).filter((id) => id && !prim.includes(id) && !skillById(id).missing).slice(0, LAYER_MAX);
}
// Делёж целого числа на n частей без потерь: часть i (остаток уходит первым частям/основной сфере).
function shareInt(total, n, i) { const base = Math.floor(total / n); return base + (i < (total % n) ? 1 : 0); }
function xpEvents() {
  const ev = [];
  for (const t of State.tasks) if (t.done) {
    const ids = taskSkills(t), n = ids.length || 1;
    const xp = t.xpAwarded || 0, gold = t.goldAwarded || 0, min = Number(t.actualMin || t.estimateMin) || 0;
    if (n <= 1) { ev.push({ date: dayOf(t), skillId: ids[0] || t.skillId || null, xp, gold, min }); }
    else ids.forEach((sid, i) => ev.push({ date: dayOf(t), skillId: sid, xp: shareInt(xp, n, i), gold: shareInt(gold, n, i), min: shareInt(min, n, i) }));
    // Фоновые слои: бонус СВЕРХУ, а не доля от основного (см. taskSkills выше — почему).
    // min:0 и gold:0 — фон не тратит время суток и не платит золотом.
    for (const lid of taskLayers(t)) ev.push({ date: dayOf(t), skillId: lid, xp: Math.max(1, Math.round(xp * LAYER_SHARE)), gold: 0, min: 0, layer: true });
  }
  const log = State.habitlog || {};
  for (const date in log) for (const hid in log[date]) { const rec = log[date][hid], h = habitById(hid); ev.push({ date, skillId: h ? h.skillId : null, xp: rec.xp || 0, gold: rec.gold || 0, min: rec.min || 0 }); }
  for (const g of State.goals || []) if (g.completedAt) { const xp = g.xpReward != null ? g.xpReward : GOAL_BONUS.xp; ev.push({ date: fmtDate(new Date(g.completedAt)), skillId: g.skillId, xp, gold: Math.round(xp * 0.35), min: 0 }); }
  // Эпизоды: период раскладывается в события ПО ДНЯМ (а не одним куском на дату окончания) —
  // именно поэтому стрик остаётся целым и Форма держится по всем дням периода, без отдельного кода.
  // min:0 намеренно: часы эпизода НЕ идут в бюджет суток. Попытка уложить погружённый день в
  // 24 часа («12 ч немецкого + 12 ч людей + наука») и была тем, что ломало модель. gold:0 —
  // золото платится за конкретные выполненные дела, а не за прожитый период.
  for (const ep of State.episodes || []) {
    const days = episodeDays(ep); if (!days.length) continue;
    const per = episodePerDayXp(ep); if (!per.length) continue;
    for (const ds of days) for (const r of per) ev.push({ date: ds, skillId: r.skillId, xp: r.xp, gold: 0, min: 0, ep: ep.id });
  }
  return ev;
}
function doneTasks() { return State.tasks.filter((t) => t.done); }
// Для календарных ачивок: моменты выполнения и группировка событий по дню
function completedTimes() { return doneTasks().map((t) => t.completedAt ? new Date(t.completedAt) : null).filter(Boolean); }
function eventsByDay() { const m = {}; for (const e of xpEvents()) (m[e.date] = m[e.date] || []).push(e); return m; }
// Импортированный «стартовый» XP (доказанное мастерство) — добавляется к заработанному
function importedXp(id) { const im = State.settings && State.settings.imported; return (im && im[id] && im[id].xp) || 0; }
function totalImportedXp() { const im = (State.settings && State.settings.imported) || {}; return Object.keys(im).reduce((s, k) => s + (im[k].xp || 0), 0); }
function earnedXp() { return xpEvents().reduce((s, e) => s + e.xp, 0); } // только заработанное в приложении (для честного лидерборда)
function overallXp() { return earnedXp() + totalImportedXp(); }
function ownSkillXp(id) { return xpEvents().reduce((s, e) => s + (e.skillId === id ? e.xp : 0), 0) + importedXp(id); }
// XP сферы. Для столба = собственный + сумма ВСЕХ потомков (агрегация вверх по дереву любой глубины).
function skillXp(id) { let xp = ownSkillXp(id); for (const c of descendantSkills(id)) xp += ownSkillXp(c.id); return xp; }
function goldEarned() { return xpEvents().reduce((s, e) => s + e.gold, 0) + (State.lootbox ? (State.lootbox.goldWon || 0) : 0); }
function goldSpent() { return (State.purchases || []).reduce((s, p) => s + (p.cost || 0), 0); }
function goldBalance() { return Math.round(goldEarned() - goldSpent()); }
// ── Форма / Momentum (импорт v2): «свежесть» по активности. НЕ трогает уровень (Proven).
//    Уровень — доказанное мастерство (не сгорает). Форма мягко падает без тренировок и легко возвращается.
const FORM_FLOOR = 25, FORM_FRESH = 3, FORM_DECAY = 21;
function skillLastActive(id) { let last = null; for (const e of xpEvents()) if (e.skillId === id && e.date && (!last || e.date > last)) last = e.date; return last; }
function daysSinceDate(dateStr) { if (!dateStr) return Infinity; const d = new Date(dateStr + 'T00:00:00'); return Math.max(0, Math.floor((Date.now() - d.getTime()) / 86400000)); }
function skillForm(id) {
  const last = skillLastActive(id);
  if (!last) return null; // ещё не тренировалось в приложении
  const ds = daysSinceDate(last);
  if (ds <= FORM_FRESH) return 100;
  return Math.round(Math.max(FORM_FLOOR, Math.min(100, 100 - ((ds - FORM_FRESH) / FORM_DECAY) * (100 - FORM_FLOOR))));
}
function overallForm() { const v = leafSkills().map((s) => skillForm(s.id)).filter((x) => x != null); return v.length ? Math.round(v.reduce((a, b) => a + b, 0) / v.length) : null; }
function formMeta(f) {
  if (f == null) return { text: 'разогрей', color: 'var(--muted)' };
  if (f >= 80) return { text: 'в форме', color: 'var(--good)' };
  if (f >= 55) return { text: 'в тонусе', color: 'var(--accent)' };
  if (f >= 38) return { text: 'расслабленно', color: 'var(--warn)' };
  return { text: 'подзаржавел', color: 'var(--bad)' };
}
function charLevel() { const c = State.settings.curve; return levelInfo(overallXp(), c.base, c.growth).level; }
function skillLevelOf(id) { const c = State.settings.curve; return levelInfo(skillXp(id), c.skillBase, c.growth).level; }

// ---- Ранги и мастерство ----
const RANKS = [
  { name: 'Новичок',     min: 1,  color: '#8b97b5', icon: '🌱', iconId: 'difficulty.easy' },
  { name: 'Ученик',      min: 3,  color: '#5fbf7a', icon: '📗', iconId: 'nav.skills' },
  { name: 'Адепт',       min: 6,  color: '#4f9ff7', icon: '🔷', iconId: 'status.xp' },
  { name: 'Эксперт',     min: 10, color: '#7c6cff', icon: '⚜️', iconId: 'goal.completed' },
  { name: 'Мастер',      min: 16, color: '#b06ff0', icon: '🔮', iconId: 'gear.m3' },
  { name: 'Грандмастер', min: 24, color: '#e0a23e', icon: '👑', iconId: 'achievement.level_30' },
  { name: 'Легенда',     min: 34, color: '#e0526a', icon: '🏆', iconId: 'system.achievement' },
];
function rankFor(level) { let r = RANKS[0]; for (const x of RANKS) if (level >= x.min) r = x; return r; }
function rankIconHTML(rank, className = '') { return satoruIconHTML((rank && rank.iconId) || 'status.xp', className, (rank && rank.icon) || '◇'); }
function rankProgress(level) {
  const idx = RANKS.reduce((a, x, i) => (level >= x.min ? i : a), 0);
  const cur = RANKS[idx], next = RANKS[idx + 1];
  if (!next) return { pct: 100, cur, next: null, toNext: 0 };
  const span = next.min - cur.min, into = level - cur.min;
  return { pct: Math.max(0, Math.min(100, Math.round((into / span) * 100))), cur, next, toNext: next.min - level };
}
function skillRank(id) { return rankFor(skillLevelOf(id)); }
function charRank() { return rankFor(charLevel()); }

// ============================================================
//  Колесо баланса v1 — РИТМ ВНИМАНИЯ за окно (НЕ стоячий уровень).
//  Философия: уровень/мастерство — храповик, НЕ сгорает. А баланс — это РИТМ:
//  сколько внимания ушло в сферу за последние недели. Затихшая сфера сама
//  проседает на колесе, потому что окно её «не видит» (естественная деградация).
//  Стартовую уровень-бирку (skillLevelOf) при этом НЕ трогаем — она остаётся.
// ============================================================
const BALANCE_WINDOW_DAYS = 21; // ~3 недели (середина «2–4 недель» из гайда §3)
const COOL_DAYS = 14;           // под-сфера «остыла», если активности не было ≥2 недель
const HOT_DAYS = 3;             // «горячо» — активность в последние дни

// --- Канонические жизненные домены (фикс, ~10, ОДИНАКОВЫ У ВСЕХ — гайд §2). ---
// Невидимый «хребет»: каждая верхняя сфера маппится на один домен (авто по имени + ручная правка).
// Нужен для (а) единой логики, (б) подсказки про пустые домены, (в) будущего мэтчинга в братстве.
// Порядок важен: autoCanon берёт ПЕРВЫЙ совпавший домен. Чистый модуль загружается
// до app.js и одновременно является production-реализацией и объектом Node-тестов.
if (!globalThis.SatoruCanonDomains) throw new Error('canon-domains.js must load before app.js');
const { CANON_DOMAINS, canonById, autoCanon, canonOf } = globalThis.SatoruCanonDomains;
// ── Честное состояние отдыха (AI-STRATEGY.md, кирпич 2) ──────────────────────────────────
// fb #6: «если я не отдыхаю, а тренируюсь — всё равно развивается Здоровье, создаётся видимость
// баланса, хотя отдыха мало». Баланс/уровни считаются по СФЕРЕ квеста — тренировка и отдых часто
// сидят в одной сфере «Здоровье», и метрика их не различает. Поэтому ищем не по сфере, а по ТЕКСТУ
// дела — тем же regex домена 'rest', что и canonOf — работает и без отдельной сферы «Отдых».
function dayHadRest(d) {
  const re = canonById('rest').re;
  if ((State.tasks || []).some((x) => x.done && dayOf(x) === d && re.test(normRu(x.title || '')))) return true;
  const log = State.habitlog && State.habitlog[d];
  if (log) for (const hid in log) { const h = (State.habits || []).find((x) => x.id === hid); if (h && re.test(normRu(h.title || ''))) return true; }
  return false;
}
// Сколько дней подряд (от сегодня назад, включительно) не было ни одного явно отдыхового дела.
function restGapDays(max) {
  const lim = max || 14; let n = 0;
  for (let i = 0; i < lim; i++) { const d = new Date(); d.setDate(d.getDate() - i); if (dayHadRest(fmtDate(d))) break; n++; }
  return n;
}
// Одна фраза честного состояния отдыха — общая для недельного зеркала, чата и движка предложений.
function restStateLine() {
  const g = restGapDays();
  return g === 0 ? 'сегодня или вчера был явный отдых' : `${g} ${plural(g, 'день', 'дня', 'дней')} подряд БЕЗ явного отдыха`;
}
// Какие домены покрыты верхними сферами (без проектов), какие — пустые (для подсказки §5.3).
function canonCoverage(spheres) {
  const list = spheres || balanceSpheres();
  const covered = new Set(); for (const s of list) { const c = canonOf(s); if (c) covered.add(c); }
  return { covered, gaps: CANON_DOMAINS.filter((d) => !covered.has(d.id)) };
}

// --- Проекты — не сферы (гайд §5.4): проект не должен быть осью колеса. ---
// Лёгкий флаг noBalance (полноценные «типы узлов» — в парковке §6.2, сюда НЕ тащим).
function isProjectSkill(sk) { return !!(sk && sk.noBalance); }
function looksLikeProject(name) { return /jufo|jugend\s*forscht|satoru|gojo|life.?rpg|диплом|курсов|реферат/i.test(normRu(name)); }
// Верхние сферы, которые реально считаются осями баланса (проекты исключены).
function balanceSpheres() { return topSkills().filter((s) => !isProjectSkill(s)); }

// --- Ритм внимания за окно ---
// Карта skillId → минуты в окне (только собственные события; агрегацию вверх делаем отдельно).
function windowMinMap(days) {
  const since = addDays(todayStr(), -((days || BALANCE_WINDOW_DAYS) - 1));
  const map = {};
  for (const e of xpEvents()) if (e.date >= since && e.skillId) map[e.skillId] = (map[e.skillId] || 0) + (e.min || 0);
  return map;
}
// Минуты сферы в окне = свои + все потомки (агрегация вверх по дереву любой глубины).
function subtreeMin(id, map) { let m = map[id] || 0; for (const c of descendantSkills(id)) m += map[c.id] || 0; return m; }
// Последняя активность в поддереве (для «остыл»): max даты события по себе + потомкам.
function skillLastActiveDeep(id) {
  let last = skillLastActive(id);
  for (const c of descendantSkills(id)) { const l = skillLastActive(c.id); if (l && (!last || l > last)) last = l; }
  return last;
}
function skillCooled(id) { if (skillXp(id) <= 0) return false; return daysSinceDate(skillLastActiveDeep(id)) >= COOL_DAYS; } // была активность, но затихла
function skillHot(id) { const d = daysSinceDate(skillLastActiveDeep(id)); return d !== Infinity && d <= HOT_DAYS; }
// Ритм набора сфер: [{ id,name,color, min, lastActive, days, cooled, hot, level }]
function rhythmFor(skills, days, map) {
  const m = map || windowMinMap(days);
  return skills.map((s) => {
    const la = skillLastActiveDeep(s.id);
    return { id: s.id, name: s.name, color: s.color, min: subtreeMin(s.id, m), lastActive: la, days: daysSinceDate(la), cooled: skillCooled(s.id), hot: skillHot(s.id), level: skillLevelOf(s.id) };
  });
}
// Колесо: ритм верхних сфер (без проектов).
function sphereRhythm(days) { return rhythmFor(balanceSpheres(), days || BALANCE_WINDOW_DAYS); }

// ══ НАГРУЗКА СФЕР — этап 3 (LIFE-CAPTURE-PLAN.md) ══════════════════════════════════════
// Запрос Альберта дословно: «чтобы понять — вот я неделю общался с рандомными типами, у меня
// перегрузилась сфера отношений, мне надо побыть одному». В часах это не выражается, поэтому
// в старой модели такого вывода не могло появиться в принципе.
//
// Считаем НЕ абсолютные часы, а превышение сферой СВОЕЙ ЖЕ нормы: свежее окно (7 дней) против
// личной базы (предыдущие 28). Нормы у всех разные, поэтому единого порога «много» не бывает —
// перегрев определяется только относительно самого себя.
//
// ⚠️ Считаем по ОПЫТУ, а не по минутам (в отличие от индекса баланса, который на минутах).
// Причина: у эпизодов и фоновых слоёв `min: 0` — по минутам неделя на выезде и весь фон были бы
// НЕВИДИМЫ, то есть ровно те перегрузы, ради которых всё и затевалось, не детектировались бы.
const LOAD_WIN = 7, LOAD_BASE_WIN = 28, LOAD_HOT = 1.7, LOAD_QUIET = 7;
function windowXpMap(fromDate, toDate) {
  const map = {};
  for (const e of xpEvents()) if (e.skillId && e.date >= fromDate && e.date <= toDate) map[e.skillId] = (map[e.skillId] || 0) + (e.xp || 0);
  return map;
}
function subtreeXp(id, map) { let v = map[id] || 0; for (const c of descendantSkills(id)) v += map[c.id] || 0; return v; }
// «Эта сфера меня восстанавливает» — снимает перегрев (предупреждать «ты перебрал отдыха» глупо).
// Это же и калибровка интроверт/экстраверт из плана: для экстраверта сфера людей — заряд, а не расход.
function sphereRestores(id) { const s = skillById(id); return !!(s && s.restores); }
function sphereLoads() {
  const T = todayStr();
  const recFrom = addDays(T, -(LOAD_WIN - 1));
  const baseTo = addDays(recFrom, -1), baseFrom = addDays(baseTo, -(LOAD_BASE_WIN - 1));
  const recMap = windowXpMap(recFrom, T), baseMap = windowXpMap(baseFrom, baseTo);
  return balanceSpheres().map((s) => {
    const rec = subtreeXp(s.id, recMap) / LOAD_WIN, base = subtreeXp(s.id, baseMap) / LOAD_BASE_WIN;
    const la = skillLastActiveDeep(s.id);
    // База должна быть содержательной: иначе первая же активность в новой сфере даёт ratio=∞
    // и приложение кричит «перегрев» там, где человек просто начал.
    const ratio = base >= 3 ? rec / base : null;
    return {
      id: s.id, name: s.name, color: s.color, rec, base, ratio,
      quietDays: la ? daysSinceDate(la) : null,
      hot: ratio != null && ratio >= LOAD_HOT && !sphereRestores(s.id),
      restores: sphereRestores(s.id),
    };
  });
}
// Перегрев + то, что при этом молчит. Именно ПАРА даёт вывод, ради которого всё делалось:
// не «ты много общался» (это и так видно), а «люди горят, а тело и учёба стоят — сделай день на себя».
function loadInsight() {
  const rows = sphereLoads();
  const hot = rows.filter((r) => r.hot).sort((a, b) => b.ratio - a.ratio);
  if (!hot.length) return null;
  const quiet = rows.filter((r) => !r.hot && skillXp(r.id) > 0 && (r.quietDays == null || r.quietDays >= LOAD_QUIET))
    .sort((a, b) => (b.quietDays || 999) - (a.quietDays || 999)).slice(0, 2);
  return { hot: hot[0], quiet };
}

// ---- Индекс баланса = РОВНОСТЬ РИТМА внимания за окно + охват (не стоячий уровень). ----
// Нудж «подтяни X» = обжитая сфера, чья доля внимания сильнее всего ниже простого таргета (равномерно).
function balanceIndex() {
  const spheres = balanceSpheres();
  const rh = sphereRhythm();
  const total = rh.reduce((a, r) => a + r.min, 0);
  const activeRh = rh.filter((r) => r.min > 0);
  if (activeRh.length < 2) return { index: 0, active: activeRh.length, total: spheres.length, weakest: null, strongest: null, windowMin: total };
  const vals = activeRh.map((r) => r.min);
  const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
  const variance = vals.reduce((a, x) => a + (x - mean) ** 2, 0) / vals.length;
  const cv = Math.sqrt(variance) / (mean || 1);
  const evenness = Math.max(0, 1 - cv);                            // 1 = идеально ровный ритм
  const coverage = activeRh.length / Math.max(1, spheres.length); // охват сфер за окно
  const index = Math.max(0, Math.min(100, Math.round(evenness * 70 + coverage * 30)));
  // Нудж: среди «обжитых» сфер (есть пожизненный опыт) — самая обделённая вниманием за окно.
  // Показываем, только если её доля < половины таргета — честно, без занудства (через любовь, не вину).
  const target = 1 / Math.max(1, spheres.length);
  let weakest = null, worst = 0.5 * target;
  for (const r of rh) { if (skillXp(r.id) <= 0) continue; const share = total ? r.min / total : 0; if (share < worst) { worst = share; weakest = r; } }
  const sorted = [...activeRh].sort((a, b) => a.min - b.min);
  return { index, active: activeRh.length, total: spheres.length, weakest, strongest: sorted[sorted.length - 1] || null, windowMin: total };
}

// ---- Подписка / Pro ----
function ent() { return (State.me && State.me.entitlement) || { tier: 'free' }; }
function isPro() { const t = ent().tier; return t === 'pro' || t === 'trial'; }
function trialDaysLeft() { const e = ent(); if (e.tier !== 'trial' || !e.trialEndsAt) return 0; return Math.max(0, Math.ceil((new Date(e.trialEndsAt).getTime() - Date.now()) / 86400000)); }

// ---- Атрибуты персонажа (выводятся из сфер жизни) ----
const ATTRIBUTES = [
  { id: 'str', name: 'Сила',         icon: '💪', color: '#e0526a', hint: 'силовые, мышцы, тело' },
  { id: 'end', name: 'Выносливость', icon: '🫁', color: '#5fbf7a', hint: 'здоровье, кардио, сон, питание' },
  { id: 'int', name: 'Интеллект',    icon: '🧠', color: '#4f86f7', hint: 'учёба, языки, чтение, код' },
  { id: 'spr', name: 'Дух',          icon: '🧘', color: '#b06ff0', hint: 'эмоции, медитация, психология' },
  { id: 'cha', name: 'Харизма',      icon: '✨', color: '#e0a23e', hint: 'общение, творчество, видео' },
  { id: 'dis', name: 'Дисциплина',   icon: '⚙️', color: '#22c1a4', hint: 'финансы, быт, бизнес, привычки' },
];
function attrById(id) { return ATTRIBUTES.find((a) => a.id === id) || ATTRIBUTES[5]; }
function guessAttr(name) {
  const n = normRu(name); // ё→е, чтобы «учеба»/«учёба» матчились одинаково
  if (/спорт|сил|качал|штанг|жим|мыш|workout|gym|подтяг|отжим|кросфит|кроссфит/.test(n)) return 'str';
  if (/бег|вынослив|кардио|велик|плав|run|марафон|ходьб|дыхан|поход|здоров|питани|нутриц|диет|сон/.test(n)) return 'end';
  if (/уч[её]б|программ|код|чтени|книг|англ|немецк|deutsch|язык|наук|study|math|школ|универ|интеллект|шахмат/.test(n)) return 'int';
  if (/медит|дух|психо|релакс|йог|вер|осознан|благодар|ментал|эмоц/.test(n)) return 'spr';
  if (/отношен|блог|общени|социал|харизм|выступл|видео|музык|творч|друз|свидан|рисов|арт|иллюстр|дизайн|фото|танц|пени|вокал/.test(n)) return 'cha';
  if (/быт|дисциплин|финанс|план|привыч|работа|бизнес|порядок|деньг|инвест|стартап|предприн/.test(n)) return 'dis';
  return 'dis';
}
// Атрибуты считаем по листьям (под-навыки + одиночные), чтобы не дублировать со столбами.
// Маппинг сфера→атрибут полностью автоматический (guessAttr) — атрибуты живут только для архетипа и силуэта.
function attrScore(attrId) { return leafSkills().filter((s) => guessAttr(s.name) === attrId).reduce((sum, s) => sum + skillLevelOf(s.id), 0); }
function attrScores() { return ATTRIBUTES.map((a) => Object.assign({}, a, { value: attrScore(a.id) })); }
// Оси радара = собственные крупные сферы юзера (его личное «десятиборье»), а не абстрактные атрибуты.
// При >8 сферах берём самые прокачанные, но сохраняем порядок из настроек (оси не скачут).
function sphereScores() {
  let list = topSkills();
  if (list.length > 8) list = [...list].sort((a, b) => skillXp(b.id) - skillXp(a.id)).slice(0, 8)
    .sort((a, b) => State.settings.skills.indexOf(a) - State.settings.skills.indexOf(b));
  return list.map((s) => ({ id: s.id, name: s.name, color: s.color, value: skillLevelOf(s.id) }));
}
function archetype() {
  const sorted = attrScores().filter((a) => a.value > 0).sort((a, b) => b.value - a.value);
  if (sorted.length === 0) return { name: 'Искатель', desc: 'Путь только начинается' };
  const top = sorted.slice(0, 2).map((a) => a.id).sort().join('+');
  const MAP = {
    'end+str': 'Атлет', 'dis+str': 'Воин дисциплины', 'int+str': 'Боевой маг', 'spr+str': 'Монах', 'cha+str': 'Герой',
    'end+int': 'Биохакер', 'dis+end': 'Марафонец воли', 'cha+end': 'Энерджайзер', 'end+spr': 'Странник',
    'dis+int': 'Стратег', 'int+spr': 'Мудрец', 'cha+int': 'Просветитель', 'dis+spr': 'Хранитель',
    'cha+spr': 'Вдохновитель', 'cha+dis': 'Лидер',
  };
  const single = { str: 'Силач', end: 'Бегун', int: 'Учёный', spr: 'Аскет', cha: 'Душа компании', dis: 'Машина воли' };
  return { name: MAP[top] || single[sorted[0].id] || 'Многогранник', desc: `${sorted[0].name}${sorted[1] ? ' + ' + sorted[1].name : ''}` };
}
function bodyBMI() { const b = State.settings.body || {}; if (!b.height || !b.weight) return null; return b.weight / ((b.height / 100) ** 2); }
// % жира по полу (ACE-диапазоны). lean=атлетично/фитнес → ИМТ с мышцами завышает. Не мед.совет.
function bodyFatCat(bf, sex) {
  const f = sex === 'f';
  const ess = f ? 13 : 5, ath = f ? 20 : 13, fit = f ? 24 : 17, acc = f ? 31 : 24;
  if (bf < ess) return { label: 'очень низкий', lean: true };
  if (bf <= ath) return { label: 'атлетично', lean: true };
  if (bf <= fit) return { label: 'фитнес', lean: true };
  if (bf <= acc) return { label: 'норма', lean: false };
  return { label: 'выше нормы', lean: false };
}

// ---- SVG: радар сфер (личное десятиборье) + схематичное телосложение ----
function radarSVG(scores) {
  const cx = 140, cy = 140, R = 88, n = scores.length, max = Math.max(3, ...scores.map((s) => s.value));
  const pt = (i, r) => { const ang = -Math.PI / 2 + i * 2 * Math.PI / n; return [cx + r * Math.cos(ang), cy + r * Math.sin(ang)]; };
  let grid = '';
  for (let g = 1; g <= 3; g++) { const poly = scores.map((_, i) => pt(i, R * g / 3).join(',')).join(' '); grid += `<polygon points="${poly}" fill="none" stroke="var(--line)" stroke-width="1"/>`; }
  let axes = '', labels = '';
  scores.forEach((s, i) => {
    const [x, y] = pt(i, R); axes += `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="var(--line)"/>`;
    const [lx, ly] = pt(i, R + 18);
    const txt = s.icon || esc(s.name.length > 11 ? s.name.slice(0, 10) + '…' : s.name);
    labels += `<text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" font-size="${s.icon ? 15 : 10.5}" ${s.icon ? '' : `fill="${esc(s.color)}" font-weight="600"`}>${txt}</text>`;
  });
  const dpoly = scores.map((s, i) => pt(i, R * Math.min(1, s.value / max)).join(',')).join(' ');
  const dots = scores.map((s, i) => { const [x, y] = pt(i, R * Math.min(1, s.value / max)); return `<circle cx="${x}" cy="${y}" r="3.5" fill="${s.color}"/>`; }).join('');
  return `<svg viewBox="0 0 280 280" class="radar"><defs><radialGradient id="radg"><stop offset="0%" stop-color="rgba(108,140,255,.35)"/><stop offset="100%" stop-color="rgba(108,140,255,.08)"/></radialGradient></defs>${grid}${axes}<polygon points="${dpoly}" fill="url(#radg)" stroke="var(--accent)" stroke-width="2"/>${dots}${labels}</svg>`;
}
function figureSVG() {
  const str = attrScore('str'), end = attrScore('end'), bmi = bodyBMI(), cr = charRank();
  const sex = (State.settings.body || {}).sex || '';
  const sh = (sex === 'f' ? 20 : 24) + Math.min(20, str * (sex === 'f' ? 1.2 : 1.6)); // плечи растут от силы; женский силуэт — уже
  const wa0 = Math.max(11, 15 + (bmi ? Math.max(0, (bmi - 21)) * 1.7 : 0) - Math.min(5, end * 0.35)); // талия от BMI, минус выносливость
  const hip = sex === 'f' ? wa0 + 7 : wa0;                                   // женский силуэт — шире бёдра
  const limb = 6 + Math.min(7, str * 0.5);                                  // толщина конечностей
  const cx = 70, c = cr.color, wa = hip;
  const torso = `${cx - sh},58 ${cx + sh},58 ${cx + wa},132 ${cx - wa},132`;
  return `<svg viewBox="0 0 140 230" class="figure">
    <ellipse cx="${cx}" cy="120" rx="${56 + charLevel() * 0.6}" ry="86" fill="${c}" opacity="0.07"/>
    <circle cx="${cx}" cy="30" r="15" fill="none" stroke="${c}" stroke-width="3"/>
    <polygon points="${torso}" fill="${c}" opacity="0.18" stroke="${c}" stroke-width="2.5" stroke-linejoin="round"/>
    <line x1="${cx - sh + 3}" y1="62" x2="${cx - sh - 8}" y2="118" stroke="${c}" stroke-width="${limb}" stroke-linecap="round"/>
    <line x1="${cx + sh - 3}" y1="62" x2="${cx + sh + 8}" y2="118" stroke="${c}" stroke-width="${limb}" stroke-linecap="round"/>
    <line x1="${cx - wa + 4}" y1="132" x2="${cx - wa - 2}" y2="206" stroke="${c}" stroke-width="${limb + 2}" stroke-linecap="round"/>
    <line x1="${cx + wa - 4}" y1="132" x2="${cx + wa + 2}" y2="206" stroke="${c}" stroke-width="${limb + 2}" stroke-linecap="round"/>
  </svg>`;
}
// ============================================================
//  Кастомизируемый аватар — послойный flat-vector SVG.
//  Каждая часть = генератор. Арт-наборы художника подключаются как новые варианты/слои.
// ============================================================
const AV_SKINS  = ['#f7d4b6', '#eebd95', '#dca579', '#c08a5e', '#9c6a45', '#6e482e'];
const AV_HAIRC  = ['#15110f', '#3b2a1d', '#5e3f25', '#8a5a2b', '#b6863f', '#dcc06a', '#9aa3ad', '#d65a5a', '#7c5cff', '#f0f0f0'];
const AV_CLOTH  = ['#6c8cff', '#46c46b', '#e0526a', '#e0a23e', '#b06ff0', '#22c1a4', '#39414f'];
const AV_PARTS  = {
  face:      { label: 'Лицо',       n: 3 },
  skin:      { label: 'Кожа',       colors: AV_SKINS },
  hair:      { label: 'Причёска',   n: 7 },
  hairColor: { label: 'Цвет волос', colors: AV_HAIRC },
  brows:     { label: 'Брови',      n: 3 },
  eyes:      { label: 'Глаза',      n: 4 },
  mouth:     { label: 'Рот',        n: 4 },
  beard:     { label: 'Борода',     n: 3 },
  glasses:   { label: 'Очки',       n: 3 },
  cloth:     { label: 'Одежда',     colors: AV_CLOTH },
};
const AV_CAT_ORDER = ['hair', 'hairColor', 'face', 'skin', 'eyes', 'brows', 'mouth', 'beard', 'glasses', 'cloth'];
function defaultAvatar() { return { face: 0, skin: 1, hair: 1, hairColor: 1, brows: 0, eyes: 0, mouth: 0, beard: 0, glasses: 0, cloth: 0 }; }
function avCfg() { return Object.assign(defaultAvatar(), (State.settings && State.settings.avatar) || {}); }
// ── Avatar Forge v1: one approved full-canvas mannequin and independent
