  const hour = doneAt && !isNaN(doneAt) ? doneAt.getHours() : null;
  const madeDay = (item.createdAt && String(item.createdAt).slice(0, 10)) || item.date;
  const doneDay = (item.completedAt && String(item.completedAt).slice(0, 10)) || item.date;
