  // --- Гайд (туториал) ---
  if (action === 'tut-next') { tutorialNext(); return; }
  if (action === 'tut-skip') { tutorialSkip(); return; }
  if (action === 'tut-restart') { const g = document.getElementById('guide'); if (g) g.remove(); tutorialStart(); return; }
  if (action === 'drip-dismiss') { dripSeen(false, el); return; }
  if (action === 'drip-open') { dripSeen(true, el); return; }
  if (action === 'select-path-choice') { selectPathChoice(el.dataset.path); return; }
  if (action === 'confirm-path-choice') { confirmPathChoice(); return; }
  if (action === 'close-path-choice') { closePathChoiceModal(); return; }
  if (action === 'path-teaser-switch') { showPathChoiceModal({ pendingPath: el.dataset.path, source: 'teaser', returnFocus: el }); return; }
  if (action === 'path-teaser-dismiss') { State.settings.pathTeaserAt = todayStr(); Store.save('settings', State.settings); render(); return; }
  try { tutorialAdvance(action); } catch {} // продвигает шаг гайда, если это его триггер (действие выполнится ниже)

  // --- Auth actions ---
  if (action === 'select-profile') {
    if (e.target.closest('#pin-form')) return; // клик внутри формы — не схлопываем
    State.selectedProfile = State.selectedProfile === id ? null : id;
    renderLoginScreen(); return;
  }
  if (action === 'go-register') { State.phase = 'register'; State.regAvatar = '⚡'; State.regName = ''; render(); return; }
  if (action === 'go-login') { State.phase = 'login'; render(); return; }
  if (action === 'go-reset') { State.phase = 'reset'; render(); return; }
  if (action === 'test-login') { loginAsTestUser(); return; }
  if (action === 'pick-avatar') { State.regAvatar = el.dataset.av; State.regName = document.querySelector('input[name="name"]')?.value || ''; render(); return; }
  if (action === 'logout') {
    el.disabled = true;
    accountJson('/api/auth/logout', { method: 'POST' }).then(async ({ response, data }) => {
      if (!response.ok) { toast(accountError(data, 'Сетевая ошибка')); return; }
      State.me = null; State.phase = 'login'; stopFocus(false); clearAllData(); State._accountSessionExpired = false;
      try { const profiles = await fetch('/api/auth/profiles'); State.profiles = profiles.ok ? await profiles.json() : []; } catch { State.profiles = []; }
      render();
    }).catch(() => toast(t('Сетевая ошибка'))).finally(() => { if (el.isConnected) el.disabled = false; }); return;
  }
  if (action === 'logout-all') {
    el.disabled = true;
    accountJson('/api/auth/logout', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ all: true }) }).then(async ({ response, data }) => {
      if (!response.ok) { toast(accountError(data, 'Сетевая ошибка')); return; }
      State.me = null; State.phase = 'login'; stopFocus(false); clearAllData(); State._accountSessionExpired = false;
      try { const profiles = await fetch('/api/auth/profiles'); State.profiles = profiles.ok ? await profiles.json() : []; } catch { State.profiles = []; }
      render();
    }).catch(() => toast(t('Сетевая ошибка'))).finally(() => { if (el.isConnected) el.disabled = false; }); return;
  }

  // --- Onboarding actions ---
  if (action === 'ob-toggle') {
    const name = el.dataset.skill;
    if (State.obSkills.has(name)) State.obSkills.delete(name); else State.obSkills.add(name);
    render(); return;
  }
  if (action === 'ob-add-custom') {
    const inp = document.getElementById('ob-custom'), col = document.getElementById('ob-color');
    const name = inp ? inp.value.trim() : '';
    if (name) { State.obSkills.add(name + '|' + (col ? col.value : '#6c8cff')); render(); }
    return;
  }
  if (action === 'ob-program') { const p = DUNGEON_PROGRAMS.find((x) => x.id === el.dataset.prog); if (p) applyProgramFresh(p); return; }
  if (action === 'add-program') { const p = DUNGEON_PROGRAMS.find((x) => x.id === el.dataset.prog); if (p) applyProgramMerge(p); return; }
  if (action === 'toggle-lb-optout') { State.settings.leaderboardOptOut = !State.settings.leaderboardOptOut; Store.save('settings', State.settings); publishLeaderboard(); State.leaderboard = null; render(); return; }
  if (action === 'ob-ai-run') { obAiRun(); return; }
  if (action === 'ob-ai-apply') { obAiApply(); return; }
  if (action === 'ob-ai-reset') { _obItems = null; _obErr = ''; renderOnboardingScreen(); return; }
  if (action === 'ob-finish') {
    if (State.obSkills.size === 0) return;
    const skills = [...State.obSkills].map((entry) => {
      const [name, color] = entry.split('|');
      const tpl = SKILL_TEMPLATES.find(t => t.name === name);
      return { id: 'sk_' + name.toLowerCase().replace(/[^a-z0-9]/g, '') + '_' + Date.now().toString(36), name, color: color || (tpl ? tpl.color : '#6c8cff') };
    });
    const settings = Object.assign(structuredClone(DEFAULT_SETTINGS), { skills });
    // saveNow: save() дебаунсится на 250 мс, а initApp() читает настройки с сервера сразу —
    // выбранные сферы не успевали записаться, и юзер получал дефолтные шесть вместо своих.
    Store.saveNow('settings', settings).then(() => {
      State.phase = 'app'; initApp(); // initApp на первом запуске сам запустит гайд «Тень ведёт» (см. конец initApp)
    });
    return;
  }

  // --- Лутбоксы / Pro / Paywall ---
  if (action === 'open-chest') { track('chest:open'); openChest(); return; }
  if (action === 'equip-title') {
    const eq = ensureCosmetics(), t = el.dataset.title || null;
    eq.title = (!t || eq.title === t) ? null : t; Store.save('settings', State.settings); render(); return;
  }
  if (action === 'equip-cosmetic') {
    if (!ownsCosmetic(el.dataset.id)) return;
    const eq = ensureCosmetics(), ty = cosmeticType(el.dataset.id);
    eq[ty] = (eq[ty] === el.dataset.id) ? null : el.dataset.id; Store.save('settings', State.settings); render(); return;
  }
  if (action === 'toggle-sound') { State.settings.sound = !!el.checked; autosaveSettings(); if (el.checked) sfx('complete'); return; }
  if (action === 'tts') { ttsSpeak(ttsTextNear(el), el, ttsContextNear(el)); return; }
  if (action === 'tts-preview') {
    ttsSpeak(TTS_PREVIEW[lang()] || TTS_PREVIEW.ru, el, 'calm');
    return;
  }
  if (action === 'chat-actions-apply') {
    const mi = Number(el.dataset.mi), msg = State.chatLog[mi];
    if (!msg || !msg.actions || msg.actionsApplied != null) return;
    const wrap = el.closest('.chat-actions');
    const checks = [...(wrap ? wrap.querySelectorAll('[data-ca]') : [])].map((c) => c.checked);
    const res = applyChatActions(msg, checks);
    msg.actionsApplied = res.total;
    if (res.total) {
      const parts = [];
      if (res.quests) parts.push(`${res.quests} ${plural(res.quests, 'квест', 'квеста', 'квестов')}`);
      if (res.habits) parts.push(`${res.habits} ${plural(res.habits, 'привычка', 'привычки', 'привычек')}`);
      if (res.goals) parts.push(`${res.goals} ${plural(res.goals, 'цель', 'цели', 'целей')}`);
      toast(`✓ ${t('Добавлено')}: ${parts.join(' · ')}`);
      sfx('complete'); track('ai:chatactions');
    }
    renderChatMessages(); render();
    return;
  }
  if (action === 'toggle-tts') { State.settings.tts = !!el.checked; autosaveSettings(); ttsStop(); render(); return; }
  if (action === 'set-ambient') {
    if (!State.settings.ambient) State.settings.ambient = {};
    State.settings.ambient.mode = el.dataset.mode;
    Store.save('settings', State.settings);
    applyAmbient(); syncDenAmbientVisual(State.settings.ambient.mode); return;
  }
  if (action === 'den-toggle-edit') {
    State._denEdit = !State._denEdit;
    State._denFocusAfterCommit = State._denEdit ? '#den-editor' : '.den-scene-tools [data-action="den-toggle-edit"]';
    track(State._denEdit ? 'den:edit-open' : 'den:edit-close');
    render();
    return;
  }
  if (action === 'den-ambient-cycle') {
    if (!State.settings.ambient) State.settings.ambient = {};
    const now = State.settings.ambient.mode || 'off';
    State.settings.ambient.mode = nextAmbientMode(now);
    Store.save('settings', State.settings);
    applyAmbient(); syncDenAmbientVisual(State.settings.ambient.mode); return;
  }
  if (action === 'den-light') {
    const den = ensureDen(), value = el.dataset.value;
    if (['auto', 'morning', 'day', 'sunset', 'night'].includes(value)) den.light = value;
    Store.save('settings', State.settings);
    syncDenLightVisual(den.light); return;
  }
  if (action === 'den-pet-count') {
    const den = ensureDen();
    den.petCount = Math.max(0, Math.min(3, Number(el.dataset.value) || 0));
    Store.save('settings', State.settings);
    render(); return;
  }
  if (action === 'den-clear') {
    const den = ensureDen(), slot = el.dataset.slot;
    if (DEN_SLOT_META[slot]) den.slots[slot] = '';
    Store.save('settings', State.settings);
    render(); return;
  }
  if (action === 'den-reset') {
    const den = ensureDen();
    den.theme = 'workshop'; den.light = 'auto'; den.petCount = 3; den.slots = { ...DEN_STARTER_SLOTS };
    Store.save('settings', State.settings);
    try { sfx('complete'); } catch {}
    toast(t('Логово вернулось к стартовой обстановке'));
    render(); return;
  }
  if (action === 'den-theme') {
    const theme = DEN_THEMES.find((x) => x.id === id);
    if (!theme || !denAcquire(theme, 'theme:' + theme.id)) return;
    const den = ensureDen(); den.theme = theme.id;
    Store.save('settings', State.settings);
    track('den:theme');
    render(); return;
  }
  if (action === 'den-item') {
    const item = denItem(id);
    if (!item || !denAcquire(item, item.id)) return;
    const den = ensureDen(); den.slots[item.slot] = item.id;
    Store.save('settings', State.settings);
    track('den:item');
    render(); return;
  }
  if (action === 'body-toad-interact' || action === 'body-toad-card-interact') {
    const mode = el.dataset.mode || 'greet';
    const scope = action === 'body-toad-interact' ? el.closest('.den-shell') : el.closest('.pet-card');
    const toad = (el.matches('[data-body-toad]') ? el : null) || (scope && scope.querySelector('[data-body-toad]'));
    if (toad && window.BodyToadV1) {
      const restoreState = bodyToadStateForSphere(id);
      if (action === 'body-toad-interact') {
        playBodyToadScene(scope, id, mode).catch(() => {});
      } else {
        window.BodyToadV1.playInteraction(toad, mode, { restoreState }).catch(() => {});
      }
      const meta = window.BodyToadV1.INTERACTIONS[mode];
      if (meta) toast(`🐸 ${t(meta.label)}`);
      try { sfx(['train', 'pushup', 'stretch', 'whistle'].includes(mode) ? 'complete' : 'click'); } catch {}
      track(`body-toad:${mode}`);
    }
    return;
  }
  if (action === 'resources-penguin-interact' || action === 'resources-penguin-card-interact') {
    const mode = el.dataset.mode || 'greet';
    const scope = action === 'resources-penguin-interact' ? el.closest('.den-shell') : el.closest('.pet-card');
    const penguin = (el.matches('[data-resources-penguin]') ? el : null) || (scope && scope.querySelector('[data-resources-penguin]'));
    if (penguin && window.ResourcesPenguinV1) {
      if (action === 'resources-penguin-interact') {
        playResourcesPenguinScene(scope, id || resourcesGuardianSphereId(), mode).catch(() => {});
      } else {
        const soloMode = mode === 'greet' ? 'blink' : mode;
        window.ResourcesPenguinV1.playSolo(penguin, soloMode, { restoreState: resourcesPenguinStateForSphere(id) }).catch(() => {});
      }
      const meta = window.ResourcesPenguinV1.INTERACTIONS[mode] || window.ResourcesPenguinV1.SOLO[mode];
      if (meta) toast(`🪙 ${t(meta.label || 'Распорядитель проверяет порядок')}`);
      try { sfx(mode === 'greet' ? 'click' : 'complete'); } catch {}
      track(`resources-penguin:${mode}`);
    }
    return;
  }
  if (action === 'den-avatar-walk') {
    cancelDenRoomAction(false);
    runDenAvatarWindowVisit({ reschedule: true }).catch(() => {});
    track('den:avatar-walk:window');
    return;
  }
  if (action === 'den-room-action') {
    const roomAction = el.dataset.roomAction || 'bench-rest';
    runDenRoomAction(roomAction).catch(() => {});
    track(`den:room-action:${roomAction}`);
    return;
  }
  if (action === 'den-avatar-pose') {
    cancelDenRoomAction(false);
    cancelDenAvatarLocomotion(false);
    const current = normalizedAvatarCorePose(el.dataset.pose || State._denAvatarPose || 'idle');
    const next = AVATAR_CORE_POSES[(AVATAR_CORE_POSES.indexOf(current) + 1) % AVATAR_CORE_POSES.length];
    State._denAvatarPose = next;
    syncDenCorePose(next).catch(() => {});
    track(`den:avatar-pose:${next}`);
    return;
  }
  if (action === 'recovery-slug-interact') {
    const mode = el.dataset.mode || 'greet';
    const scope = el.closest('.den-shell');
    if (scope && window.RecoverySlugV1 && window.RecoverySlugV1.INTERACTIONS[mode]) {
      playRecoverySlugScene(scope, mode).catch(() => {});
      toast(`🌿 ${t(window.RecoverySlugV1.INTERACTIONS[mode].label)}`);
      try { sfx(mode === 'greet' ? 'click' : 'complete'); } catch {}
      track(`recovery-slug:${mode}`);
    }
    return;
  }
  if (action === 'recovery-slug-react') {
    const scope = el.closest('.den-shell, .pet-card') || document;
    const slug = el.matches('[data-recovery-slug]') ? el : scope.querySelector('[data-recovery-slug]');
    if (slug && window.RecoverySlugV1) {
      window.RecoverySlugV1.reassure(slug, recoverySlugState()).catch(() => {});
      toast(`🌿 ${t('Кацую замедляет дыхание рядом с тобой')}`);
      try { sfx('click'); } catch {}
      track('recovery-slug:reassure');
    }
    return;
  }
  if (action === 'character-wardrobe-slot') {
    const slot = characterWardrobeV1Slot(el.dataset.slot);
    if (!slot) return;
    State._characterWardrobeSlot = slot.id;
    State._characterFocusAfterCommit = `[data-action="character-wardrobe-slot"][data-slot="${slot.id}"]`;
    render();
    return;
  }
  if (action === 'character-wardrobe-filter') {
    const filter = el.dataset.filter === 'new' ? 'new' : 'all';
    State._characterWardrobeFilter = filter;
    State._characterFocusAfterCommit = `[data-action="character-wardrobe-filter"][data-filter="${filter}"]`;
    render();
    return;
  }
  if (action === 'character-wardrobe-equip') {
    const slot = characterWardrobeV1Slot(el.dataset.slot);
    const item = slot && characterWardrobeV1Item(slot.id, el.dataset.item);
    if (!slot || !item || !AVATAR_SLOT_VALUES[slot.runtimeKey].has(item.value)) return;
    const owned = characterWardrobeV1Owned();
    if (item.value !== 'none' && !owned.has(item.id) && !characterWardrobeV1Equipped(slot, item)) return;
    rememberCharacterWardrobeV1Item(item.id);
    State._characterWardrobeSlot = slot.id;
    State._characterFocusAfterCommit = `[data-wardrobe-item="${item.id}"]`;
    const next = nextAvatarAppearance({ slots: { [slot.runtimeKey]: item.value } });
    queueAvatarAppearanceRender(next).then(() => toast(`${t(item.value === 'none' ? 'Снять' : 'Надето')}: ${t(item.label)}`)).catch(() => {
      State._characterFocusAfterCommit = '';
    });
    return;
  }
  if (action === 'avatar-core-pose') {
    const pose = normalizedAvatarCorePose(el.dataset.pose);
    State._avatarCorePose = pose;
    const editor = document.getElementById('avatar-editor');
    swapAvatarCoreStack(editor && editor.querySelector('.avatar-core-stack'), pose).catch(() => {});
    editor && editor.querySelectorAll('[data-action="avatar-core-pose"]').forEach((button) => {
      const selected = button.dataset.pose === pose;
      button.classList.toggle('is-selected', selected);
      button.setAttribute('aria-pressed', String(selected));
    });
    return;
  }
  if (action === 'avatar-core-gender') {
    setAvatarCoreGender(el.dataset.gender).catch(() => toast('Не удалось загрузить аватар'));
    return;
  }
  if (action === 'den-pet-react') {
    el.classList.remove('is-reacting'); void el.offsetWidth; el.classList.add('is-reacting');
    setTimeout(() => el.classList.remove('is-reacting'), 1100);
    try { sfx('complete'); } catch {}
    return;
  }

  // --- Живой компаньон (Finch-модель) ---
  if (action === 'comp-rename') { State._compForm = 'name'; render(); return; }
  if (action === 'comp-check') { State._compForm = el.dataset.kind === 'e' ? 'e' : 'm'; render(); return; }
  if (action === 'comp-cancel') { State._compForm = null; render(); return; }
  if (action === 'moment-close') { closeMoment(); return; }
  if (action === 'moment-replay') {
    // Встреча по замыслу бывает раз в день — без этого её нельзя ни посмотреть,
    // ни показать другому, пока не наступит следующее утро.
    closeMoment();
    showMoment(new Date().getHours() >= 17 ? 'e' : 'm');
    return;
  }
  if (action === 'moment-pet') {
    // То же, что «погладить» на карточке, но из момента: закрываем его следом,
    // чтобы жест завершал встречу, а не оставлял человека в оверлее.
    const cm = ensureCompanion();
    if (cm.pet !== today) {
      cm.pet = today; cm.bond += 1; cm.lastSeen = today; State._compAway = 0;
      Store.save('settings', State.settings);
      try { sfx('complete'); } catch {}
      toast('💛 ' + esc(cm.name) + ' ' + t('жмурится от тепла'));
      if (window.ShadowRig) window.ShadowRig.setTransient('happy', 1000);
    }
    closeMoment(); render(); return;
  }
  if (action === 'comp-pet') {
    const c = ensureCompanion();
    if (c.pet === today) return;
    c.pet = today; c.bond += 1; c.lastSeen = today; State._compAway = 0;
    Store.save('settings', State.settings);
    if (typeof sfx === 'function') sfx('complete');
    toast('💛 ' + esc(c.name) + ' жмурится от тепла');
    if (window.ShadowRig) window.ShadowRig.setTransient('happy', 1000);
    render(); return;
  }

  // --- Питомцы по сферам ---
  if (action === 'pet-feed') { track('pet:feed');
    const art = el.closest('.pet-art'), svg = art && art.querySelector('.pet-svg');
    const toad = art && art.querySelector('[data-body-toad]');
    if (toad && window.BodyToadV1) window.BodyToadV1.playInteraction(toad, 'greet', { restoreState: bodyToadStateForSphere(id) }).catch(() => {});
    if (svg) {
      svg.classList.remove('pet-nom'); void svg.offsetWidth; svg.classList.add('pet-nom'); // рестарт анимации
      const dom = (petTraits(id)[0] || {}).icon || '⭐', treat = PET_TREAT[dom] || PET_TREAT['⭐'];
      const food = document.createElement('span'); food.className = 'pet-food'; food.innerHTML = satoruIconHTML(treat.iconId, 'pet-treat-icon', treat.fallback);
      art.appendChild(food); setTimeout(() => food.remove(), 1000);
    }
    if (typeof sfx === 'function') sfx('complete');
    toast('💛 ' + esc(petName(id)) + ' доволен');
    return;
  }
  if (action === 'pet-hint') { const tr = petTraits(id)[0]; if (tr && tr.hint) toast(t(tr.hint)); return; }
  if (action === 'pet-rename') { State._petRename = id; render(); return; }
  if (action === 'pet-rename-cancel') { State._petRename = null; render(); return; }
  if (action === 'open-fortune-editor') { showFortuneEditor(id); return; }
  if (action === 'close-fortune-editor') { document.getElementById('fortune-editor')?.remove(); render(); return; }
  if (action === 'fortune-editor-tab') { showFortuneEditor(id, el.dataset.tab); return; }
  if (action === 'pick-fortune-skin') {
    const skins = ensureFortuneSkins(), skinId = el.dataset.value;
    if (FORTUNE_SKINS[skinId]) skins[id] = skinId; else delete skins[id];
    Store.save('settings', State.settings);
    try { sfx('complete'); } catch {}
    showFortuneEditor(id, 'skin'); return;
  }
  if (action === 'pick-fortune-prop') {
    const props = ensureFortuneProps(), propId = el.dataset.value;
    if (FORTUNE_PROPS[propId]) props[id] = propId; else delete props[id];
    Store.save('settings', State.settings);
    try { sfx('complete'); } catch {}
    showFortuneEditor(id, 'prop'); return;
  }
  if (action === 'pick-fortune-wear') {
    const slot = el.dataset.slot;
    if (!setPetWearSlot(id, slot, el.dataset.value || '')) { toast(t('Этот предмет нельзя надеть в выбранный слот')); return; }
    Store.save('settings', State.settings);
    try { sfx('complete'); } catch {}
    showFortuneEditor(id, slot); return;
  }

  // --- Снаряжение / гир ---
  if (action === 'buy-gear') {
    const it = gearById(id); if (!it) return;
    const g = ensureGear(); if (g.owned.includes(id)) return;
    if (charLevel() < it.lvl) { toast(`🔒 Откроется на ур.${it.lvl}`); return; }
    if (goldBalance() < it.cost) { toast('Недостаточно золота'); return; }
    g.owned.push(id);
    if (!g.equipped[it.slot]) g.equipped[it.slot] = id; // авто-надеть в пустой слот
    State.purchases = State.purchases || [];
    State.purchases.push({ id: 'p_' + uid(), gearId: id, name: it.name, cost: it.cost, at: new Date().toISOString() });
    Store.save('settings', State.settings); Store.save('purchases', State.purchases);
    if (systemMode()) systemNarrate('ПРЕДМЕТ ПОЛУЧЕН', `${it.icon} ${it.name} · ${gearBonusLabel(it)}`); else toast(`⚔️ Получено: ${it.name}`);
    sfx('coin'); checkAchievements(); render(); return;
  }
  if (action === 'equip-gear') {
    const it = gearById(id); if (!it) return; const g = ensureGear();
    if (!g.owned.includes(id)) return;
    g.equipped[it.slot] = (g.equipped[it.slot] === id) ? null : id;
    Store.save('settings', State.settings); sfx('complete'); render(); return;
  }
  if (action === 'equip-relic') {
    const g = ensureGear(), uidv = el.dataset.uid;
    if (!(g.relics || []).some((r) => r.uid === uidv)) return;
    g.equipped.relic = (g.equipped.relic === uidv) ? null : uidv;
    Store.save('settings', State.settings); sfx('complete'); render(); return;
  }
  if (action === 'set-lang') { State.settings.lang = el.dataset.lang; autosaveSettings(); render(); return; }
  if (action === 'strava-connect') { window.location.href = '/api/strava/connect'; return; }
  if (action === 'strava-sync') { stravaSync(); return; }
  if (action === 'strava-disconnect') {
    if (!confirm('Отключить Strava? Уже импортированные тренировки останутся, новые синхронизироваться не будут.')) return;
    fetch('/api/strava/disconnect', { method: 'POST' }).then(() => { State.strava = null; toast('Strava отключён'); render(); }).catch(() => toast('Ошибка'));
    return;
  }
  if (action === 'open-path-choice') { showPathChoiceModal({ pendingPath: el.dataset.path || null, source: 'settings', returnFocus: el }); return; }
  if (action === 'toggle-system-skin-off') { State.settings.systemSkinOff = !!el.checked; autosaveSettings(); applyTheme(); render(); return; }
  if (action === 'toggle-antagonist-mute') { State.settings.pathAntagonistMuted = !!el.checked; autosaveSettings(); render(); return; }
